// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    DEP_BANK c;

    uint256 internal reentrantObservedBalance;
    bool internal reentered;
    bool internal sawReentry;

    function setUp() public {
        c = new DEP_BANK();
        c.SetLogFile(address(new LogFile()));
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint128).max);

        c.SetMinSum(amount);
        vm.deal(address(this), amount);
        vm.prank(address(this));
        c.Deposit{value: amount}();

        reentrantObservedBalance = type(uint256).max;
        reentered = false;
        sawReentry = false;

        vm.prank(address(this));
        c.Collect(amount);

        assertTrue(sawReentry && reentrantObservedBalance == 0 && c.balances(address(this)) == 0);
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            sawReentry = true;
            reentrantObservedBalance = c.balances(address(this));
            c.Collect(0);
        }
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string Data;
        uint Val;
        uint Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}
